private enum class Tab { TOOLS, RECORDS, MINE }
private enum class Page { HOME, MODULE, FEATURE, DIAGNOSIS, RECORDS, MINE }

@Composable private fun Text(text: String, color: Color = Color.Unspecified, modifier: Modifier = Modifier, fontSize: androidx.compose.ui.unit.TextUnit = androidx.compose.ui.unit.TextUnit.Unspecified, fontWeight: FontWeight? = null, letterSpacing: androidx.compose.ui.unit.TextUnit = androidx.compose.ui.unit.TextUnit.Unspecified, lineHeight: androidx.compose.ui.unit.TextUnit = androidx.compose.ui.unit.TextUnit.Unspecified, maxLines: Int = Int.MAX_VALUE) {
    androidx.compose.material3.Text(text, color = color, modifier = modifier, fontSize = fontSize, fontWeight = fontWeight, letterSpacing = letterSpacing, lineHeight = lineHeight, maxLines = maxLines)
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); enableEdgeToEdge(); setContent { 抚心Theme { FuxinApp() } } }
}

@Composable fun FuxinApp() {
    var tab by rememberSaveable { mutableStateOf(Tab.TOOLS) }; var page by rememberSaveable { mutableStateOf(Page.HOME) }
    var selectedModule by rememberSaveable { mutableStateOf("healing") }; var selectedFeature by rememberSaveable { mutableStateOf("companion") }
    Surface(Modifier.fillMaxSize(), color = Night) { Scaffold(containerColor = Night, bottomBar = {
        if (page == Page.HOME || page == Page.RECORDS || page == Page.MINE) NavigationBar(containerColor = SurfaceNight) {
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceEvenly) {
                NavItem("工具", "✦", tab == Tab.TOOLS, Modifier.weight(1f)) { tab = Tab.TOOLS; page = Page.HOME }
                NavItem("记录", "◌", tab == Tab.RECORDS, Modifier.weight(1f)) { tab = Tab.RECORDS; page = Page.RECORDS }
                NavItem("我的", "○", tab == Tab.MINE, Modifier.weight(1f)) { tab = Tab.MINE; page = Page.MINE }
            }
        }
    }) { inset -> Box(Modifier.padding(inset)) { when (page) {
        Page.HOME -> HomePage({ selectedModule = it; page = Page.MODULE }, { page = Page.DIAGNOSIS })
        Page.MODULE -> ModulePage(selectedModule, { page = Page.HOME }, { selectedFeature = it; page = Page.FEATURE }, { page = Page.DIAGNOSIS })
        Page.FEATURE -> FeaturePage(selectedModule, selectedFeature) { page = Page.MODULE }
        Page.DIAGNOSIS -> DiagnosisPage({ page = Page.HOME }, { selectedModule = it; page = Page.MODULE })
        Page.RECORDS -> RecordsPage { tab = Tab.TOOLS; page = Page.HOME }; Page.MINE -> MinePage { tab = Tab.TOOLS; page = Page.HOME }
    } } } }
}

@Composable private fun NavItem(label: String, icon: String, selected: Boolean, modifier: Modifier = Modifier, click: () -> Unit) { Column(modifier.clip(RoundedCornerShape(14.dp)).clickable { click() }.padding(vertical = 7.dp), horizontalAlignment = Alignment.CenterHorizontally) { Text(icon, if (selected) Coral else TextDim, fontSize = 22.sp); Text(label, if (selected) WarmWhite else TextDim, fontSize = 11.sp, fontWeight = if (selected) FontWeight.Bold else FontWeight.Normal) } }

@Composable private fun Brand() { Row(verticalAlignment = Alignment.CenterVertically) { Box(Modifier.size(38.dp).clip(RoundedCornerShape(13.dp)).background(Brush.linearGradient(listOf(Coral, Orange))), contentAlignment = Alignment.Center) { Text("心", Night, fontSize = 18.sp, fontWeight = FontWeight.Black) }; Text("FUXIN", WarmWhite, fontSize = 14.sp, fontWeight = FontWeight.Bold, letterSpacing = 3.sp, modifier = Modifier.padding(start = 11.dp)) } }

@Composable private fun EmotionArt(color: Color, compact: Boolean = false) { Canvas(Modifier.size(if (compact) 76.dp else 142.dp)) { val c = Offset(size.width * .56f, size.height * .45f); drawCircle(Brush.radialGradient(listOf(color.copy(alpha = .9f), color.copy(alpha = .06f), Color.Transparent), c, size.minDimension * .72f), size.minDimension * .72f, c); drawArc(color, 215f, 235f, false, c - Offset(size.minDimension * .33f, size.minDimension * .33f), Size(size.minDimension * .66f, size.minDimension * .66f), style = Stroke(size.minDimension * .035f, cap = StrokeCap.Round)); drawArc(ElectricYellow.copy(alpha = .8f), 28f, 150f, false, c - Offset(size.minDimension * .21f, size.minDimension * .21f), Size(size.minDimension * .42f, size.minDimension * .42f), style = Stroke(size.minDimension * .035f, cap = StrokeCap.Round)); drawCircle(WarmWhite, size.minDimension * .045f, c) } }

@Composable private fun HomePage(openModule: (String) -> Unit, openDiagnosis: () -> Unit) { LazyColumn(Modifier.fillMaxSize().padding(horizontal = 20.dp), contentPadding = PaddingValues(top = 24.dp, bottom = 32.dp)) { item { Brand(); Spacer(Modifier.height(28.dp)); Card(colors = CardDefaults.cardColors(containerColor = SurfaceNight), shape = RoundedCornerShape(30.dp), modifier = Modifier.fillMaxWidth()) { Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Color(0xFF321A32), Color(0xFF1C1725)))).padding(22.dp)) { Column { Text("TODAY / 现在", Coral, fontSize = 11.sp, fontWeight = FontWeight.Bold, letterSpacing = 2.sp); Text("情绪很满的时候，\n先站回自己这一边。", WarmWhite, fontSize = 28.sp, fontWeight = FontWeight.Black, lineHeight = 36.sp, modifier = Modifier.padding(top = 12.dp)); Text("不用立刻决定关系。先做一个让你轻一点的动作。", TextMuted, fontSize = 13.sp, lineHeight = 20.sp, modifier = Modifier.padding(top = 10.dp)); Button(onClick = openDiagnosis, colors = ButtonDefaults.buttonColors(containerColor = Coral, contentColor = Night), shape = RoundedCornerShape(16.dp), modifier = Modifier.fillMaxWidth().padding(top = 20.dp).height(52.dp)) { Text("开始关系自诊  →", fontWeight = FontWeight.Bold) } }; EmotionArt(Orange, true) } }; Row(Modifier.fillMaxWidth().padding(top = 25.dp, bottom = 14.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text("或者，直接选择你现在需要的", TextMuted, fontSize = 13.sp); Text("3 个方向", ElectricYellow, fontSize = 13.sp, fontWeight = FontWeight.Bold) } }; items(modules) { ModuleCard(it) { openModule(it.id) } }; item { Spacer(Modifier.height(22.dp)); Text("不评判你的选择  ·  不自动发送  ·  记录只属于你", TextDim, fontSize = 11.sp); Text("抚心是 AI 关系支持工具，不替代心理咨询或医疗诊断。", TextDim, fontSize = 10.sp, modifier = Modifier.padding(top = 9.dp)) } } }

@Composable private fun ModuleCard(module: FuxinModule, click: () -> Unit) { val color = moduleColor(module.id); Card(colors = CardDefaults.cardColors(containerColor = SurfaceNight), shape = RoundedCornerShape(24.dp), modifier = Modifier.fillMaxWidth().padding(vertical = 7.dp).clickable { click() }) { Column(Modifier.padding(18.dp)) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.Top) { Column(Modifier.weight(1f)) { Text("${module.marker}  ${module.title}", WarmWhite, fontSize = 20.sp, fontWeight = FontWeight.Bold); Text(module.subtitle, color, fontSize = 12.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 5.dp)) }; EmotionArt(color, true) }; Text(module.intro, TextMuted, fontSize = 13.sp, lineHeight = 19.sp, modifier = Modifier.padding(top = 4.dp)); Row(Modifier.padding(top = 16.dp), verticalAlignment = Alignment.CenterVertically) { Text("${module.features.size} 个工具  ·  约 5 分钟", TextDim, fontSize = 11.sp); Spacer(Modifier.weight(1f)); Button(onClick = click, colors = ButtonDefaults.buttonColors(containerColor = color, contentColor = Night), contentPadding = PaddingValues(horizontal = 16.dp), shape = RoundedCornerShape(12.dp), modifier = Modifier.height(40.dp)) { Text("直接开始", fontSize = 12.sp, fontWeight = FontWeight.Bold) } } } } }

@Composable private fun ModulePage(moduleId: String, back: () -> Unit, openFeature: (String) -> Unit, diagnosis: () -> Unit) { val module = modules.first { it.id == moduleId }; val color = moduleColor(moduleId); Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal = 20.dp)) { Text("‹  ${module.title}", TextMuted, fontSize = 17.sp, modifier = Modifier.padding(top = 22.dp).clickable { back() }); Card(colors = CardDefaults.cardColors(containerColor = SurfaceNight), shape = RoundedCornerShape(28.dp), modifier = Modifier.fillMaxWidth().padding(top = 22.dp)) { Row(Modifier.padding(20.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("${module.marker}  ${module.subtitle}", color, fontSize = 12.sp, fontWeight = FontWeight.Bold); Text(module.intro, WarmWhite, fontSize = 24.sp, fontWeight = FontWeight.Black, lineHeight = 31.sp, modifier = Modifier.padding(top = 10.dp)) }; EmotionArt(color, true) } }; Text("TODAY / 今天先做这一件事", ElectricYellow, fontSize = 11.sp, fontWeight = FontWeight.Bold, letterSpacing = 1.sp, modifier = Modifier.padding(top = 28.dp)); Button(onClick = { openFeature(module.features.first().id) }, colors = ButtonDefaults.buttonColors(containerColor = color, contentColor = Night), shape = RoundedCornerShape(16.dp), modifier = Modifier.fillMaxWidth().padding(top = 10.dp).height(56.dp)) { Text("${module.features.first().title}  →", fontSize = 16.sp, fontWeight = FontWeight.Bold) }; Text("功能工具", WarmWhite, fontSize = 20.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 30.dp, bottom = 10.dp)); module.features.chunked(2).forEach { pair -> Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) { pair.forEach { feature -> ToolCard(feature, color, Modifier.weight(1f)) { openFeature(feature.id) } }; if (pair.size == 1) Spacer(Modifier.weight(1f)) } }; OutlinedButton(onClick = diagnosis, shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth().padding(top = 24.dp).height(48.dp)) { Text("不确定？重新帮我找方向", TextMuted) }; Spacer(Modifier.height(30.dp)) } }

@Composable private fun ToolCard(feature: FuxinFeature, color: Color, modifier: Modifier = Modifier, click: () -> Unit) { Card(colors = CardDefaults.cardColors(containerColor = SurfaceNight), shape = RoundedCornerShape(18.dp), modifier = modifier.padding(vertical = 5.dp).clickable { click() }) { Column(Modifier.padding(14.dp).height(94.dp)) { Text("✦", color, fontSize = 18.sp); Text(feature.title, WarmWhite, fontSize = 14.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 8.dp)); Text(feature.description, TextDim, fontSize = 10.sp, maxLines = 1, modifier = Modifier.padding(top = 4.dp)) } } }

@Composable private fun FeaturePage(moduleId: String, featureId: String, back: () -> Unit) { val feature = modules.first { it.id == moduleId }.features.firstOrNull { it.id == featureId } ?: modules.first().features.first(); var input by rememberSaveable { mutableStateOf("") }; var selected by rememberSaveable { mutableStateOf("") }; var saved by rememberSaveable { mutableStateOf(false) }; val options = featureOptions(featureId); Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal = 20.dp)) { Text("‹  返回模块", TextMuted, fontSize = 17.sp, modifier = Modifier.padding(top = 22.dp).clickable { back() }); Text("抚心 · 小功能", Coral, fontSize = 11.sp, fontWeight = FontWeight.Bold, letterSpacing = 1.5.sp, modifier = Modifier.padding(top = 34.dp)); Text(feature.title, WarmWhite, fontSize = 29.sp, fontWeight = FontWeight.Black, modifier = Modifier.padding(top = 10.dp)); Text(feature.description, TextMuted, fontSize = 14.sp, modifier = Modifier.padding(top = 7.dp)); Card(colors = CardDefaults.cardColors(containerColor = SurfaceNight), shape = RoundedCornerShape(22.dp), modifier = Modifier.fillMaxWidth().padding(top = 28.dp)) { Column(Modifier.padding(18.dp)) { Text(featurePrompt(featureId), WarmWhite, fontSize = 17.sp, fontWeight = FontWeight.Bold); options.forEach { option -> OptionRow(option, selected == option) { selected = option } }; if (options.isEmpty() || featureId in textFeatures) OutlinedTextField(input, { input = it }, Modifier.fillMaxWidth().height(170.dp).padding(top = 14.dp), placeholder = { Text("写下你的想法……", color = TextDim) }, colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = Coral, unfocusedBorderColor = DividerNight, focusedTextColor = WarmWhite, unfocusedTextColor = WarmWhite, cursorColor = Coral)) } }; Button(onClick = { saved = true }, colors = ButtonDefaults.buttonColors(containerColor = Coral, contentColor = Night), shape = RoundedCornerShape(16.dp), modifier = Modifier.fillMaxWidth().padding(top = 22.dp).height(56.dp)) { Text(if (saved) "已保存 ✓" else "保存这次记录", fontWeight = FontWeight.Bold) }; if (saved) Text("已保存到你的记录中 · 可以随时删除", ElectricYellow, fontSize = 12.sp, modifier = Modifier.padding(top = 15.dp)); Spacer(Modifier.height(30.dp)) } }

@Composable private fun OptionRow(option: String, selected: Boolean, click: () -> Unit) { Row(Modifier.fillMaxWidth().padding(top = 12.dp).clip(RoundedCornerShape(13.dp)).background(if (selected) Color(0xFF49212A) else Color.Transparent).border(1.dp, if (selected) Coral else DividerNight, RoundedCornerShape(13.dp)).clickable { click() }.padding(14.dp), verticalAlignment = Alignment.CenterVertically) { Text(if (selected) "●" else "○", if (selected) Coral else TextDim, modifier = Modifier.width(27.dp)); Text(option, if (selected) WarmWhite else TextMuted, fontSize = 13.sp) } }

