private fun moduleColor(id: String) = when (id) { "healing" -> Coral; "reconciliation" -> Orange; else -> ElectricPurple }
private val textFeatures = setOf("companion", "diary", "draft", "risk-check", "unsent", "supporter", "necessary-contact", "facts", "relation-facts", "relapse")
private fun featurePrompt(id: String) = when (id) { "companion" -> "此刻，你最想说些什么？"; "mood" -> "此刻的情绪和强度"; "opportunity" -> "目前是否仍有基本尊重和沟通空间？"; "urge-delay" -> "你想把这次冲动延迟多久？"; else -> "从这里开始" }
private fun featureOptions(id: String): List<String> = when (id) { "mood" -> listOf("难过", "思念", "愤怒", "焦虑", "麻木", "平静"); "grounding" -> listOf("4-6 呼吸", "五感落地", "暂停联系", "转移注意力"); "motivation" -> listOf("仍然爱着对方", "害怕失去", "孤独和想念", "不甘心结束", "愿意共同改变"); "opportunity" -> listOf("是，仍有基本沟通", "不确定，需要更多事实", "不是，已明确拒绝或不安全"); "communication-goal" -> listOf("了解近况", "表达我的改变", "请求一次见面", "寻求明确答复"); "cooling" -> listOf("保存并开始冷却", "重新修改后再看", "决定不发送"); "outcome" -> listOf("愿意继续沟通", "回复但需要空间", "没有回复", "明确拒绝", "我决定暂停联系"); "detachment-goal" -> listOf("24 小时", "3 天", "7 天", "自定义"); "trigger" -> listOf("照片或聊天记录", "社交媒体动态", "某个地点或时间", "孤独或难过", "相似的事物"); "urge-delay" -> listOf("5 分钟", "15 分钟", "30 分钟"); "urge-log" -> listOf("成功延迟了", "查看了但没有联系", "联系了对方", "转去做替代行动"); "alternatives" -> listOf("出门走 10 分钟", "洗澡或喝水", "联系支持我的人", "做 5 分钟专注任务", "睡前放松"); "boundaries" -> listOf("写一条体面结束的回复", "停止继续追问", "处理被拒绝后的情绪", "转入戒断计划"); "detachment-plan" -> listOf("完成一次冲动延迟", "整理一个触发源", "做一个生活恢复动作", "写下不发送的话"); else -> emptyList() }
